const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const memphis = ee.Geometry.Point([-90.0489, 35.1495]).buffer(10000); // 10km buffer around Memphis
  const date2014 = ee.Date('2014-02-27');
  const date2019 = ee.Date('2019-02-25');

  // 2. Data Acquisition - JRC Monthly Water History
  const jrcCol = ee.ImageCollection('JRC/GSW1_4/MonthlyHistory');

  // Get images for both dates
  const img2014 = jrcCol.filterDate(date2014, date2014.advance(1, 'month')).first();
  const img2019 = jrcCol.filterDate(date2019, date2019.advance(1, 'month')).first();

  // Check if images exist
  const count2014 = img2014 ? 1 : 0;
  const count2019 = img2019 ? 1 : 0;

  console.log(`2014 Images: ${count2014}, 2019 Images: ${count2019}`);

  if (count2014 === 0 || count2019 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Count water pixels (values 1-100 indicate water)
  const waterMask2014 = img2014.select('water').gte(1).and(img2014.select('water').lte(100));
  const waterMask2019 = img2019.select('water').gte(1).and(img2019.select('water').lte(100));

  // Count water pixels
  const waterCount2014 = waterMask2014.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: memphis,
    scale: 1000,
    maxPixels: 1e9
  }).get('water');

  const waterCount2019 = waterMask2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: memphis,
    scale: 1000,
    maxPixels: 1e9
  }).get('water');

  const [count14, count19] = await Promise.all([
    waterCount2014.getInfo(),
    waterCount2019.getInfo()
  ]);

  console.log(`2014 Water Pixels: ${count14}, 2019 Water Pixels: ${count19}`);

  // 4. Validation checks
  if (count14 === null || count19 === null || count14 === undefined || count19 === undefined) {
    console.log("<answer>C3</answer>");
    return;
  }

  if (count14 === 0 && count19 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Final comparison
  console.log(`Water extent change: ${((count19 - count14) / count14 * 100).toFixed(1)}%`);

  if (count19 > count14) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
